/// <summary>
/// PaffH 15.04.25
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(InventItemInventSetup), DataEventType::Updating)
    ,SuppressBPWarning('BPParameterNotUsed', '"e" is not used')]
public static void InventItemInventSetup_onUpdating(Common sender, DataEventArgs e)
{
    InventItemInventSetup inventItemInventSetup = sender as InventItemInventSetup;
    for (int i = 1; i <= 4; i++)
    {
        FieldId fieldnum1;
        switch (i)
        {
            case 1:
                fieldnum1 = fieldNum(InventItemInventSetup, MultipleQty);
                break;
            case 2:
                fieldnum1 = fieldNum(InventItemInventSetup, LowestQty);
                break;
            case 3:
                fieldnum1 = fieldNum(InventItemInventSetup, HighestQty);
                break;
            case 4:
                fieldnum1 = fieldNum(InventItemInventSetup, StandardQty);
                break;
        }
        if (inventItemInventSetup.orig().(fieldnum1) != inventItemInventSetup.(fieldnum1))
        {
            // save changeLog POP specific Datamanagement
            NDXPOPspecificDataManagementHistory::saveChangeFromInventTable(
                inventItemInventSetup.inventTable().RecId
                , inventItemInventSetup
                , fieldnum1
                , [inventItemInventSetup.orig().(fieldnum1)]
                , [inventItemInventSetup.(fieldnum1)]);
        }
    }
}
